@startuml
skinparam classAttributeIconSize 0

interface UserRepository {
  ~ Optional<UserEntity> findByEmail(String)
  ~ boolean existsByNumber(String)
}

interface DoctorProfileRepository {
  ~ Optional<DoctorProfileEntity> findByLicenseNumber(String)
}

interface FileUploadInterface {
}

class CloudinaryUploadServiceImpl {
  - Cloudinary cloudinary
  + String uploadFile(MultipartFile)
  - File convertMultiPartToFile(MultipartFile)
}

class UserEntity {
  - String id
  - String name
  - String email
  - String password
  - AccountStatusENUM status
}

class DoctorProfileEntity {
  - String id
  - String licenseNumber
  - String licenseImageUrl
}

class RoleEntity {
  - Long id
  - RoleENUM name
}

' Relaciones
UserRepository ..> UserEntity : "Gestiona >"
DoctorProfileRepository ..> DoctorProfileEntity : "Gestiona >"
FileUploadInterface <|.. CloudinaryUploadServiceImpl : "Implementa"

UserEntity "1" -- "1" RoleEntity : "Tiene >"
UserEntity "1" -- "1" DoctorProfileEntity : "Extiende a >"
@enduml

